import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    total_sum = sum(a)

    result = []
    for i in range(n):
        if a[i] * n == total_sum:
            result.append(i + 1)  # Convert to 1-indexed

    print(len(result))
    if result:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
"}

