def are_equivalent(s1, s2):
    """Check if two strings are equivalent."""
    if s1 == s2:
        return True

    if len(s1) % 2 != 0:
        return False

    mid = len(s1) // 2
    a1, a2 = s1[:mid], s1[mid:]
    b1, b2 = s2[:mid], s2[mid:]

    # Check both combinations
    return (are_equivalent(a1, b1) and are_equivalent(a2, b2)) or \
           (are_equivalent(a1, b2) and are_equivalent(a2, b1))

def main():
    s1 = input().strip()
    s2 = input().strip()

    if are_equivalent(s1, s2):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
"}

