def solve():
    s = input().strip()
    p = input().strip()

    n = len(s)
    m = len(p)

    # dp[x] = maximum number of matches with exactly x characters removed
    # We'll use a DP approach where we iterate over the string and update dp

    dp = [-1] * (n + m + 1)  # Extra space to avoid index out of range
    dp[0] = 0  # With 0 characters removed, we have 0 matches

    # Iterate over the string and update dp
    for i in range(n - m + 1):
        if s[i:i+m] == p:
            # This is a match - we can consider using it
            for x in range(n, -1, -1):
                if dp[x] != -1:
                    dp[x + m] = max(dp[x + m], dp[x] + 1)

    # Now also handle the case where we just remove characters that are not part of any match
    for x in range(n, -1, -1):
        if dp[x] != -1:
            dp[x + 1] = max(dp[x + 1], dp[x])

    # Now dp[x] gives the maximum number of matches for exactly x characters removed

    result = []
    for x in range(n + 1):
        result.append(str(dp[x] if dp[x] != -1 else 0))

    print(' '.join(result))

solve()
