import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Read grid
    grid = []
    for _ in range(n):
        row = []
        for _ in range(m):
            row.append(int(next(it)))
        grid.append(row)

    total = 0

    # Count by row and color
    for row in grid:
        color_counts = {}
        for color in set(row):
            color_counts[color] = row.count(color)

        # Add single cells
        for color, count in color_counts.items():
            if count > 0:
                total += count

        # Add pairs (non-empty subsets of size 2 that share a row)
        for color, count in color_counts.items():
            if count >= 2:
                total += count * (count - 1) // 2

    # Count by column and color
    for col in range(m):
        color_counts = {}
        for row in range(n):
            color = grid[row][col]
            color_counts[color] = color_counts.get(color, 0) + 1

        # Add single cells
        for color, count in color_counts.items():
            if count > 0:
                total += count

        # Add pairs (non-empty subsets of size 2 that share a column)
        for color, count in color_counts.items():
            if count >= 2:
                total += count * (count - 1) // 2

    print(total)

if __name__ == "__main__":
    solve()
"}

