import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    arr.sort()

    result = [0] * n
    result[0] = 1

    for i in range(1, n):
        if arr[i] != 1:
            result[i] = min(arr[i-1], arr[i])
        else:
            result[i] = min(arr[i-1], arr[i] + 1)

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
"}

