def solve():
    t = int(input())
    for _ in range(t):
        n, x, y = map(int, input().split())

        # Find all divisors of (y - x)
        diff = y - x
        divisors = set()
        for i in range(1, int(diff**0.5) + 1):
            if diff % i == 0:
                divisors.add(i)
                divisors.add(diff // i)

        # Try each divisor as potential difference
        best = None
        for d in divisors:
            # Try to place x and y in the progression
            # We need enough elements to fill the progression
            # Try placing x at position i and y at position j
            # We need |i - j| >= diff / d
            # And we need enough room for the rest of the elements

            # Let's try all possible positions for x and y
            found = False
            for i in range(n):
                for j in range(n):
                    if i == j:
                        continue

                    # Check if we can fit both x and y with difference d
                    # The distance between x and y in terms of steps is |i - j|
                    # We need d * |i - j| >= y - x
                    if d * abs(i - j) >= diff:
                        # Check if we can fill the remaining positions
                        # The start position should be at least 1 - (n-1)*d
                        start = 1 - (n-1)*d

                        # Check if we can fit both x and y in the range [start, start + (n-1)*d]
                        if start <= x <= start + (n-1)*d and start <= y <= start + (n-1)*d:
                            # Create the progression
                            progression = []
                            for k in range(n):
                                progression.append(start + k * d)

                            # Check if x and y are actually in the progression
                            found_x = False
                            found_y = False
                            for val in progression:
                                if val == x:
                                    found_x = True
                                if val == y:
                                    found_y = True

                            if found_x and found_y:
                                found = True
                                best = progression
                                break
                if found:
                    break

        if best:
            print(' '.join(map(str, best)))
        else:
            # If no solution found (shouldn't happen per problem statement)
            print(-1)

solve()
