import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        n = int(data[idx])
        idx += 1

        # Read the grid
        grid = []
        for i in range(n):
            grid.append(list(data[idx]))
            idx += 1

        # Function to check if there are any winning configurations
        def has_win():
            # Check rows
            for row in grid:
                for i in range(len(row) - 2):
                    if row[i] == row[i+1] == row[i+2]:
                        return True

            # Check columns
            for j in range(len(grid[0])):
                for i in range(len(grid) - 2):
                    if grid[i][j] == grid[i+1][j] == grid[i+2][j]:
                        return True

            return False

        # Keep modifying until no winning configuration exists
        while has_win():
            # Find any winning configuration and break it
            for i in range(n):
                for j in range(n):
                    # Check if there's a winning configuration starting at (i, j)
                    if i + 2 < n and grid[i][j] == grid[i+1][j] == grid[i+2][j]:
                        # Break the sequence by changing the middle token
                        grid[i+1][j] = 'X' if grid[i+1][j] == 'O' else 'O'
                        break
                else:
                    # No winning configuration in this row, check columns
                    for j in range(n):
                        if j + 2 < n and grid[i][j] == grid[i+1][j] == grid[i+2][j]:
                            # Break the sequence by changing the middle token
                            grid[i+1][j] = 'X' if grid[i+1][j] == 'O' else 'O'
                            break
                    else:
                        # No winning configuration, continue to next row
                        continue
                    break
                break

        # Print the result
        for row in grid:
            print(''.join(row))

if __name__ == "__main__":
