    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        n = int(data[idx])
        idx += 1

        # Read the grid
        grid = []
        for i in range(n):
            grid.append(list(data[idx]))
            idx += 1

        # Function to check if there are any winning configurations
        def has_win():
            # Check rows
            for i in range(n):
                for j in range(n - 2):
                    if grid[i][j] == grid[i][j+1] == grid[i][j+2]:
                        return True

            # Check columns
            for j in range(n):
                for i in range(n - 2):
                    if grid[i][j] == grid[i+1][j] == grid[i+2][j]:
                        return True

            return False

        # Find and break any winning configuration
        while has_win():
            # Find any winning configuration
            found = False
            for i in range(n):
                for j in range(n - 2):
                    if grid[i][j] == grid[i][j+1] == grid[i][j+2]:
                        # Break the sequence by changing the middle token
                        grid[i][j+1] = 'X' if grid[i][j+1] == 'O' else 'O'
                        found = True
                        break
                if found:
                    break
            if not found:
                for j in range(n):
                    for i in range(n - 2):
                        if grid[i][j] == grid[i+1][j] == grid[i+2][j]:
                            # Break the sequence by changing the middle token
                            grid[i+1][j] = 'X' if grid[i+1][j] == 'O' else 'O'
                            found = True
                            break
                    if found:
                        break

        # Print the result
        for row in grid:
            print(''.join(row))

