def find_kth_char(n, k):
    # Base case: f0
    if n == 0:
        base = "What are you doing at the end of the world? Are you busy? Will you save us?"
        if k > len(base):
            return '.'
        return base[k-1]

    # Length of f_{n-1}
    len_prev = 140 * (2 ** (n-1)) - 69

    # Total length of fn
    len_n = 140 * (2 ** n) - 69

    if k > len_n:
        return '.'

    # Prefix: "What are you doing while sending " (length 34)
    if k <= 34:
        return "What are you doing while sending "[k-1]

    # First f_{n-1}
    if k <= 34 + len_prev:
        return find_kth_char(n-1, k-34)

    # Middle: "? Are you busy? Will you send " (length 34)
    if k <= 34 + len_prev + 34:
        return "? Are you busy? Will you send "[k - 34 - len_prev - 1]

    # Second f_{n-1}
    if k <= 34 + len_prev + 34 + len_prev:
        return find_kth_char(n-1, k - 34 - len_prev - 34)

    # Suffix: "?"
    return "?"[0]

