def is_prime(num):
    """Check if a number is prime."""
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def solve(n):
    """Find a graph with n vertices that meets the conditions."""
    # Try to connect vertex 1 to all other vertices
    if is_prime(n - 1):
        # Vertex 1 has degree n-1 (prime)
        # Other vertices have degree 1 (not prime)
        # So we need to connect them in pairs
        edges = []
        for i in range(2, n):
            # Connect vertex i to vertex 1
            edges.append((1, i))

        # Pair up the remaining vertices
        remaining = list(range(2, n))
        for i in range(0, len(remaining) - 1, 2):
            edges.append((remaining[i], remaining[i + 1]))

        # Check if this works
        degrees = [0] * n
        for u, v in edges:
            degrees[u - 1] += 1
            degrees[v - 1] += 1

        if all(is_prime(d) for d in degrees) and is_prime(len(edges)):
            return edges

    # Try a different approach: connect vertex 1 to some vertices, others to others
    for k in range(2, n):
        if is_prime(k - 1) and is_prime(n - k):  # Vertex 1 connects to k-1, others connect to n-k
            edges = []
            # Vertex 1 connects to vertices 2 to k
            for i in range(2, k + 1):
                edges.append((1, i))

            # Other vertices connect to each other in groups of size n-k
            group_size = n - k
            for i in range(k + 1, n + 1):
                edges.append((i, i + 1))  # Connect in a line
                if i % group_size == 0:
                    edges.append((i, i - group_size))

        degrees = [0] * n
        for u, v in edges:
            degrees[u - 1] += 1
            degrees[v - 1] += 1

        if all(is_prime(d) for d in degrees) and is_prime(len(edges)):
            return edges

    return None

