{"code": "
n = int(input())
a = list(map(int, input().split()))

# dp[i] = length of LIS ending at index i
# cnt[i] = number of LIS ending at index i
# prev[i] = predecessor in the LIS

dp = [1] * n
cnt = [1] * n
prev = [-1] * n

for i in range(n):
    for j in range(i):
        if a[j] < a[i] and dp[j] + 1 > dp[i]:
            dp[i] = dp[j] + 1
            cnt[i] = cnt[j]
            prev[i] = j
        elif a[j] < a[i] and dp[j] + 1 == dp[i]:
            cnt[i] += cnt[j]

max_len = max(dp)
total_cnt = cnt[dp.index(max_len)]

# Compute LIS starting from each position (reverse direction)

dp2 = [1] * n
cnt2 = [1] * n
prev2 = [-1] * n

for i in range(n):
    for j in range(i, -1, -1):
        if a[j] > a[i] and dp2[j] + 1 > dp2[i]:
            dp2[i] = dp2[j] + 1
            cnt2[i] = cnt2[j]
            prev2[i] = j
        elif a[j] > a[i] and dp2[j] + 1 == dp2[i]:
            cnt2[i] += cnt2[j]

result = ['0'] * n

for i in range(n):
    if dp[i] + dp2[i] - 1 < max_len:
        # Not in any LIS
        result[i] = '1'
    elif dp[i] + dp2[i] - 1 == max_len:
        # In at least one LIS
        if cnt[i] * cnt2[i] == total_cnt:
            # In all LIS
            result[i] = '3'
        else:
            # In some but not all LIS
            result[i] = '2'
    else:
        # Shouldn't happen
        result[i] = '1'

print(''.join(result))
"}

