    for i in range(n - 2):
        substr = s[i:i+3]
        if substr == 'zyx':
            pos_zyx.append(i)
        elif substr == 'xzy':
            pos_xzy.append(i)
        elif substr == 'yxz':
            pos_yxz.append(i)

    # For each test, check if the substring contains any of the patterns
    for _ in range(m):
        l, r = map(int, sys.stdin.readline().split())
        l -= 1  # 0-indexed
        r -= 1

        # Check if any pattern starts within [l, r-2]
        contains = False

        if pos_zyx and l <= pos_zyx[-1] <= r - 2:
