def count_beautiful_strings(n, m, g):
    """Count the number of beautiful strings with n zeros, m ones, and final character g."""

    # Memoization dictionary
    memo = {}

    def dp(n, m, target):
        """Return the number of ways to get target from a string with n zeros and m ones."""
        if (n, m, target) in memo:
            return memo[(n, m, target)]

        # Base case: single character
        if n + m == 1:
            if n == 1 and target == 0:
                return 1
            elif m == 1 and target == 1:
                return 1
            else:
                return 0

        # Recursive case: we can merge the last two characters
        # '0' and '0' → '1', need remaining to be 1
        if n >= 2:
            result = dp(n - 2, m, 1)
        else:
            result = 0

        # '0' and '1' → '0', need remaining to be 0
        if n >= 1 and m >= 1:
            result += dp(n - 1, m - 1, 0)

        # '1' and '1' → '0', need remaining to be 0
        if m >= 2:
            result += dp(n, m - 2, 0)

        memo[(n, m, target)] = result
        return result

    return dp(n, m, g)

