def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # dp[i] = maximum number of problems in a valid contest ending with problem i
    dp = [1] * n  # At least 1 problem (just the problem itself)

    # For each problem i, find the best j < i such that there exists some k with a_k in (a[j], 2*a[j]] and a_k < a[i]
    for i in range(n):
        for j in range(i):
            # Check if there exists some problem k with a_k in (a[j], 2*a[j]] and a_k < a[i]
            # This means we need to find the smallest index k such that a_k > a[j] and a_k <= 2*a[j]
            # If such a k exists and k < i, then we can extend the contest

            # Find the smallest index k > j such that a_k > a[j] and a_k <= 2*a[j]
            left, right = j + 1, n - 1
            found = False
            while left <= right:
                mid = (left + right) // 2
                if a[mid] > a[j] and a[mid] <= 2 * a[j]:
                    found = True
                    break
                elif a[mid] <= a[j]:
                    left = mid + 1
                else:
                    right = mid - 1

            if found:
                # There exists some k with a_k in (a[j], 2*a[j]] and a_k < a[i]
                dp[i] = max(dp[i], dp[j] + 1)

    print(max(dp))

