def longest_increasing_subsequence_length(arr):
    """Find the length of the longest increasing subsequence (LIS)"""
    lis = []
    for num in arr:
        # Find the first index in lis that is >= num
        left, right = 0, len(lis)
        while left < right:
            mid = (left + right) // 2
            if lis[mid] >= num:
                right = mid
            else:
                left = mid + 1
        if left == len(lis):
            lis.append(num)
        else:
            lis[left] = num
    return len(lis)


def count_lis_occurrences(arr):
    """Count how many longest increasing subsequences contain each element"""
    n = len(arr)
    if n == 0:
        return []

    # Find length of LIS
    lis_length = longest_increasing_subsequence_length(arr)

    # For each element, find left[i] = length of LIS ending at index i
    left = [1] * n
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i]:
                left[i] = max(left[i], left[j] + 1)

    # For each element, find right[i] = length of LIS starting from index i
    right = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[j] > arr[i]:
                right[i] = max(right[i], right[j] + 1)

    # Determine group for each element
    result = []
    for i in range(n):
        if left[i] + right[i] - 1 != lis_length:
            result.append('1')  # Group 1: Not in any LIS
        else:
            # Check if it's in all LIS
            # Remove element i and check LIS length
            temp = arr[:i] + arr[i+1:]
            temp_lis_length = longest_increasing_subsequence_length(temp)
            if temp_lis_length != lis_length:
                result.append('3')  # Group 3: In all LIS
            else:
                result.append('2')  # Group 2: In some but not all LIS

    return ''.join(result)

