def count_lucky_digits(x):
    return sum(1 for d in str(x) if d in '47')

def generate_lucky_numbers(limit):
    lucky = []
    def dfs(num):
        if num > limit:
            return
        if num > 0:
            lucky.append(num)
        dfs(num * 10 + 4)
        dfs(num * 10 + 7)
    dfs(0)
    return lucky

def get_intervals(start, end):
    lucky = generate_lucky_numbers(end)
    intervals = []
    prev = start
    for lucky_num in lucky:
        if lucky_num > end:
            break
        if lucky_num > prev:
            intervals.append((prev, lucky_num - 1, count_lucky_digits(prev)))
        prev = lucky_num + 1
    if prev <= end:
        intervals.append((prev, end, count_lucky_digits(prev)))
    return intervals

def find_pattern(start, length):
    intervals = get_intervals(start, start + length - 1)
    pattern = []
    for (s, e, count) in intervals:
        pattern.append((s, e, count))
