import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Read grid
    grid = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(m)]
        grid.append(row)

    # Count single cells (each cell is a valid set)
    result = n * m

    # Count sets where all cells in a row have the same color
    for row in grid:
        if all(cell == row[0] for cell in row):
            result += 1

    # Count sets where all cells in a column have the same color
    for col_idx in range(m):
        same = True
        first = grid[0][col_idx]
        for row_idx in range(1, n):
            if grid[row_idx][col_idx] != first:
                same = False
                break
        if same:
            result += 1

    sys.stdout.write(str(result))

if __name__ == "__main__":
    solve()
