import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Read grid
    grid = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(m)]
        grid.append(row)

    result = 0

    # Try all non-empty subsets of cells
    for mask in range(1, 1 << (n * m)):
        # Extract cells in this subset
        cells = []
        for i in range(n * m):
            if mask & (1 << i):
                row = i // m
                col = i % m
                cells.append((row, col))

        # Check if all cells have the same color
        color = grid[cells[0][0]][cells[0][1]]
        all_same_color = all(grid[r][c] == color for r, c in cells)
        if not all_same_color:
            continue

        # Check if every two cells share row or column
        valid = True
        for i in range(len(cells)):
            for j in range(i + 1, len(cells)):
                r1, c1 = cells[i]
                r2, c2 = cells[j]
                if r1 != r2 and c1 != c2:
                    valid = False
                    break
            if not valid:
                break

        if valid:
            result += 1

    sys.stdout.write(str(result))

if __name__ == "__main__":
    solve()
