        return False

    # Count frequency of each number
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    # Find min and max numbers
    min_num = min(nums)
    max_num = max(nums)

    # Check if we can form a continuous sequence from min to max
    for num in range(min_num, max_num + 1):
        if num == min_num:
            # Need at least one occurrence of min_num + 1
            if min_num + 1 not in freq:
                return False
        elif num == max_num:
            # Need at least one occurrence of max_num - 1
            if max_num - 1 not in freq:
                return False
        else:
            # Need at least one occurrence of num-1 or num+1
            if (num - 1 not in freq) and (num + 1 not in freq):
                return False

    return True

n = int(input())
nums = list(map(int, input().split()))

if can_form_circle(nums):
    print("YES")
else:
    print("NO")
