import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    a = int(data[0])
    b = int(data[1])
    c = int(data[2])

    for x in range(c // a + 1):
        rem = c - a * x
        if rem < 0:
            break
        if rem % b == 0:
            print("YES")
            return
    print("NO")

if __name__ == "__main__":
    solve()
"}

