    """Compute the length of the LIS and arrays left and right"""
    n = len(sequence)

    # left[i]: length of longest increasing subsequence ending at i
    left = [1] * n
    for i in range(1, n):
        for j in range(i):
            if sequence[j] < sequence[i] and left[j] + 1 > left[i]:
                left[i] = left[j] + 1

    # right[i]: length of longest increasing subsequence starting at i (from end)
    right = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if sequence[i] < sequence[j] and right[j] + 1 > right[i]:
                right[i] = right[j] + 1

    return left, right

