for i in range(n):
    if left[i] + right[i] - 1 == lis_length:
        # Can be in some LIS
        if left[i] == lis_length or right[i] == lis_length:
            # Must be in every LIS
            result.append('3')
        else:
            # In at least one but not every LIS
            result.append('2')
