import heapq

def solve():
    N = int(input())
    board = []
    for _ in range(N):
        board.append(list(map(int, input().split())))

    # Find start and end positions
    start_pos = None
    end_pos = None
    for i in range(N):
        for j in range(N):
            if board[i][j] == 1:
                start_pos = (i, j)
            if board[i][j] == N * N:
                end_pos = (i, j)

    # Directions for each piece
    directions = {
        'knight': [(2, 1), (1, 2), (-1, 2), (-2, 1),
                   (2, -1), (1, -2), (-1, -2), (-2, -1)],
        'bishop': [(1, 1), (1, -1), (-1, 1), (-1, -1)],
        'rook': [(1, 0), (-1, 0), (0, 1), (0, -1)]
    }

    # Dijkstra's algorithm
    # State: (x, y, piece, target)
    # We'll use a priority queue with (steps, replacements, x, y, piece, target)
    pq = []

    # Try starting with each piece
    for piece in ['knight', 'bishop', 'rook']:
        heapq.heappush(pq, (0, 0, start_pos[0], start_pos[1], piece, 2))

    visited = {}

    while pq:
        steps, repl, x, y, piece, target = heapq.heappop(pq)

        # If we've reached the end
        if target == N * N:
            print(steps, repl)
            return

        # If we've already visited this state with equal or fewer steps
        state = (x, y, piece, target)
        if state in visited:
            if visited[state] <= steps:
                continue
        visited[state] = steps

        # Try moving with current piece
        if piece in directions:
            for dx, dy in directions[piece]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < N:
                    # Check if we reached a new target
                    new_target = target
                    if board[nx][ny] == target + 1:
                        new_target = target + 1
                    heapq.heappush(pq, (steps + 1, repl, nx, ny, piece, new_target))

        # Try replacing the piece
