import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    k = int(data[0])
    s = data[1]
    q = int(data[2])
    queries = data[3:3+2*q]

    # Build the tournament tree structure
    n_teams = 2 ** k
    n_games = n_teams - 1

    # For each game, we'll store which teams can win from that game to the root
    # For leaf nodes (teams), they can win from themselves
    can_win = [set() for _ in range(n_games)]

    # For each team, it can win from its position to the root
    for i in range(n_teams):
        can_win[i] = {i + 1}

    # Process games from bottom to top
    for i in range(n_teams - 1, 0, -1):
        left_team = 2 * i
        right_team = 2 * i + 1

        # Get the result of game i
        result = s[i-1]

        # Determine which teams can win from this game to the root
        left_set = can_win[left_team - 1]
        right_set = can_win[right_team - 1]

        if result == '0':
            # Only left team can win
            valid_teams = set()
            for team in left_set:
                if team in left_set:
                    valid_teams.add(team)
            can_win[i-1] = valid_teams
        elif result == '1':
            # Only right team can win
            valid_teams = set()
            for team in right_set:
                if team in right_set:
                    valid_teams.add(team)
            can_win[i-1] = valid_teams
        elif result == '?':
            # Both teams can win
            valid_teams = set()
            for team in left_set:
                if team in left_set:
                    valid_teams.add(team)
            for team in right_set:
                if team in right_set:
                    valid_teams.add(team)
            can_win[i-1] = valid_teams
        else:
            # Invalid character
            pass

    # Output the number of teams that can win from the root
    print(len(can_win[0]))

solve()
