import sys

def can_win_from_game(team, game_idx, s):
    # game_idx is 1-indexed
    # Returns True if team can be champion starting from this game

    # Base case: if we're at the root
    if game_idx == 1:
        return True

    left_team_idx = 2 * game_idx
    right_team_idx = 2 * game_idx + 1

    # Get the two teams that this game represents
    # We need to determine which team (if any) can win this game
    left_team = left_team_idx
    right_team = right_team_idx

    result = s[game_idx - 1]

    if result == '0':
        # Lower-indexed team wins
        if team == left_team:
            return can_win_from_game(team, left_team_idx, s)
        elif team == right_team:
            return can_win_from_game(team, right_team_idx, s)
        else:
            return False
    elif result == '1':
        # Higher-indexed team wins
        if team == left_team:
            return can_win_from_game(team, left_team_idx, s)
        elif team == right_team:
            return can_win_from_game(team, right_team_idx, s)
        else:
            return False
    elif result == '?':
        # Either team can win
        # If team is on the left side
        if team == left_team:
            return can_win_from_game(team, left_team_idx, s)
        # If team is on the right side
        elif team == right_team:
            return can_win_from_game(team, right_team_idx, s)
        else:
            return False
    else:
        return False


