    right_team_idx = 2 * game_idx + 1

    # Get the two teams that this game represents
    # We need to determine which team (if any) can win this game
    left_team = left_team_idx
    right_team = right_team_idx

    result = s[game_idx - 1]

    if result == '0':
        # Lower-indexed team wins
        if team == left_team:
            # Team needs to win the left subtree game
            return can_win_from_game(team, left_team_idx, s)
        elif team == right_team:
            # Team needs to win the right subtree game
            return can_win_from_game(team, right_team_idx, s)
        else:
            return False
    elif result == '1':
        # Higher-indexed team wins
        if team == left_team:
            # Team needs to win the left subtree game
            return can_win_from_game(team, left_team_idx, s)
        elif team == right_team:
            # Team needs to win the right subtree game
            return can_win_from_game(team, right_team_idx, s)
        else:
            return False
    elif result == '?':
        # Either team can win
        # If team is on the left side
        if team == left_team:
            return can_win_from_game(team, left_team_idx, s)
        # If team is on the right side
        elif team == right_team:
            return can_win_from_game(team, right_team_idx, s)
        else:
            return False
    else:
        return False


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    k = int(data[0])
    s = data[1]
    q = int(data[2])
    queries = data[3:3+2*q]

    # Process queries
    results = []

    for i in range(q):
        p = int(queries[2*i])
        c = queries[2*i + 1]

        # Update the string
        s = s[:p-1] + c + s[p:]

        # Count how many teams can be champions
        count = 0
        for team in range(1, 2**k + 1):
            if can_win_from_game(team, 1, s):
                count += 1

        results.append(str(count))

    print('\n'.join(results))

solve()

