def has_winning(grid, n):
    """Find a winning configuration (three consecutive same tokens) and return the position of the middle token"""
    # Check rows
    for i in range(n):
        for j in range(n - 2):
            if grid[i][j] == grid[i][j+1] == grid[i][j+2] != '.':
                return (i, j+1)  # Return position of the middle token

    # Check columns
    for j in range(n):
        for i in range(n - 2):
            if grid[i][j] == grid[i+1][j] == grid[i+2][j] != '.':
                return (i+1, j)  # Return position of the middle token

    return None

