        while True:
            mid_pos = has_winning(grid, n)
            if mid_pos is None:
                break

            i, j = mid_pos
            # Change the middle token to the opposite type
            grid[i][j] = 'X' if grid[i][j] == 'O' else 'O'

        for row in grid:
            print(''.join(row))

