def find_char(n, k):
    # Base case: f0
    if n == 0:
        f0 = "What are you doing at the end of the world? Are you busy? Will you save us?"
        if k > len(f0):
            return '.'
        return f0[k - 1]

    # Calculate length of fn
    len_fn = 142 * (2 ** n) - 70

    if k > len_fn:
        return '.'

    # Prefix: "What are you doing while sending " (38 chars)
    prefix = "What are you doing while sending "
    if k <= len(prefix):
        return prefix[k - 1]

    # Middle: "? Are you busy? Will you send " (31 chars)
    middle = "? Are you busy? Will you send "
    if k <= len(prefix) + len(f0) + len(middle):
        # First occurrence of fi-1
        return find_char(n - 1, k - len(prefix))

    if k <= len(prefix) + len(f0) + len(middle) + len(f0):
        # Middle part
        return middle[k - len(prefix) - len(f0) - 1]

    # Second occurrence of fi-1
    return find_char(n - 1, k - len(prefix) - 2 * len(f0) - len(middle))

q = int(input())
result = []
for _ in range(q):
    n, k = map(int, input().split())
    result.append(find_char(n, k))

print(''.join(result))
