import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    if n % 2 == 0:
        print("No")
        return

    if a[0] % 2 == 0 or a[-1] % 2 == 0:
        print("No")
        return

    # DP: dp[i] = True if we can reach index i with even/odd number of segments
    # dp is a list of size n+1, where dp[i] is a boolean array [even, odd]
    dp = [[False] * 2 for _ in range(n+1)]
    dp[0][0] = True  # 0 segments, even count

    for i in range(n):
        for j in range(i+1, n+1):
            length = j - i
            if length % 2 == 0:  # length odd: j-i odd => j-i+1 odd
                if a[i] % 2 != 1 or a[j-1] % 2 != 1:
                    continue
                # transition
                for k in range(2):
                    if dp[i][k]:
                        dp[j][(k+1)%2] = True

    if dp[n][1]:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
