def can_break_shield(a, b, c):
    """Check if we can deal exactly c damage with Ebony (a) and Ivory (b) bullets"""
    # Check if c is at least one of a or b (we need at least one bullet from at least one gun)
    if c < a and c < b:
        return False

    # Try all possible numbers of Ebony bullets
    max_ebony_bullets = c // a
    for x in range(max_ebony_bullets + 1):
        remaining = c - (a * x)
        # Check if remaining damage can be achieved with Ivory bullets
        if remaining % b == 0:
            return True

    return False

