def solve():
    n, x = map(int, input().split())
    a = list(map(int, input().split()))

    # Build the graph: for each beaver i, if a[i-1] != 0, then a[i-1] must be immediately before i
    # This forms chains

    # Find all valid topological orderings (linear extensions of the partial order)
    # We'll use backtracking

    # For each beaver, we'll track which ones can be placed next
    can_place = set(range(1, n + 1))

    # For each beaver i, we track which beavers must come immediately before it
    # This will help us check constraints
    must_precede = {}
    for i in range(1, n + 1):
        if a[i - 1] != 0:
            must_precede[i] = a[i - 1]

    # For each beaver i, we track which beavers must come immediately after it
    must_succeed = {}
    for i in range(1, n + 1):
        if a[i - 1] != 0:
            must_succeed[a[i - 1]] = i

    # We need to find all valid orderings
    orderings = []

    def backtrack(current_order):
        if len(current_order) == n:
            orderings.append(current_order.copy())
            return

        # Find all beavers that can be placed next
        next_beavers = []
        for beaver in can_place:
            # Check if all constraints are satisfied
            satisfied = True

            # Check if any beaver must come immediately before this one
            if beaver in must_precede:
                predecessor = must_precede[beaver]
                if predecessor in current_order:
                    # Check if predecessor is immediately before beaver
                    predecessor_idx = current_order.index(predecessor)
                    if predecessor_idx + 1 != len(current_order):
                        satisfied = False

            # Check if any beaver must come immediately after this one
            if beaver in must_succeed:
                successor = must_succeed[beaver]
                if successor in current_order:
                    # Check if beaver is immediately before successor
                    beaver_idx = current_order.index(beaver)
                    successor_idx = current_order.index(successor)
                    if beaver_idx + 1 != successor_idx:
                        satisfied = False

            if satisfied:
                next_beavers.append(beaver)

        # Try placing each valid beaver next
        for beaver in next_beavers:
            current_order.append(beaver)
            can_place.remove(beaver)
            backtrack(current_order)
            current_order.pop()
            can_place.add(beaver)

    backtrack([])

    # Find all possible positions of beaver x
    positions = set()
    for ordering in orderings:
        pos = ordering.index(x) + 1  # 1-indexed position
        positions.add(pos)

    # Sort and print
    for pos in sorted(positions):
        print(pos)

